def compute(vars):
    notices = vars["v1"]
    terminated = vars["v2"]

    if notices == 0:
        return None

    ratio = terminated / notices
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "employees_with_notices": notices,
            "employees_terminated": terminated,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage",
            },
        },
    }
